/* Wave 3 browser QA: headless Chromium (puppeteer-core driving the
 * Playwright-cache Chromium), phone viewport 420px, against a local
 * static server started by this script.
 *
 * Covers: one planet-in-sign page, one planet-in-house page, one
 * sign page, the library hub (all generated by tools/build-library.js),
 * and the full-reading birth chart for test case N1 (1990-06-15
 * 14:30, New York), counting the rendered reading blocks: the big
 * three (3) + every planet in its sign (10) + house readings for
 * Sun, Moon, Mercury, Venus and Mars (5) = 18 expected.
 *
 * Run:  node tools/qa-wave3.js
 */
"use strict";
const puppeteer = require(process.env.QA_PUPPETEER || "/tmp/qa/node_modules/puppeteer-core");
const fs = require("fs");
const http = require("http");
const os = require("os");
const path = require("path");

const ROOT = path.join(__dirname, "..");
const PORT = 8139;
const BASE = "http://127.0.0.1:" + PORT;

function defaultChrome() {
  const cache = path.join(os.homedir(), ".cache/ms-playwright");
  for (const d of fs.readdirSync(cache).filter((x) => x.startsWith("chromium-")).sort().reverse()) {
    const p = path.join(cache, d, "chrome-linux64", "chrome");
    if (fs.existsSync(p)) return p;
  }
  throw new Error("no chromium in playwright cache");
}
const CHROME = process.env.CHROME_BIN || defaultChrome();

const results = [];
function check(name, ok, detail) {
  results.push({ name, ok, detail: detail || "" });
  console.log((ok ? "PASS  " : "FAIL  ") + name + (detail ? "  ::  " + detail : ""));
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const MIME = { ".html": "text/html", ".css": "text/css", ".js": "text/javascript",
  ".json": "application/json", ".xml": "application/xml", ".txt": "text/plain",
  ".png": "image/png", ".svg": "image/svg+xml" };
function serve() {
  return new Promise((resolve) => {
    const srv = http.createServer((req, res) => {
      let p = decodeURIComponent(req.url.split("?")[0].split("#")[0]);
      if (p.endsWith("/")) p += "index.html";
      const file = path.join(ROOT, p);
      if (!file.startsWith(ROOT) || !fs.existsSync(file) || fs.statSync(file).isDirectory()) {
        res.writeHead(404); res.end("not found"); return;
      }
      res.writeHead(200, { "Content-Type": MIME[path.extname(file)] || "application/octet-stream" });
      fs.createReadStream(file).pipe(res);
    });
    srv.listen(PORT, "127.0.0.1", () => resolve(srv));
  });
}

/* Date and time inputs mangle keyboard entry in headless Chrome, so
 * their values are set by script, as in qa-wave2.js. */
async function setVal(page, sel, value) {
  await page.evaluate((s, v) => {
    const el = document.querySelector(s);
    el.value = v;
    el.dispatchEvent(new Event("input", { bubbles: true }));
    el.dispatchEvent(new Event("change", { bubbles: true }));
  }, sel, value);
}
async function pickPlace(page, inputSel, listSel, query, expectText) {
  await page.click(inputSel);
  await page.type(inputSel, query, { delay: 30 });
  await page.waitForFunction(
    (sel, txt) => [...document.querySelectorAll(sel + " li")]
      .some((li) => li.textContent.includes(txt)),
    { timeout: 15000 }, listSel, expectText);
  await page.evaluate((sel, txt) => {
    const li = [...document.querySelectorAll(sel + " li")].find((x) => x.textContent.includes(txt));
    li.dispatchEvent(new MouseEvent("mousedown", { bubbles: true }));
  }, listSel, expectText);
  await sleep(150);
}

(async () => {
  const srv = await serve();
  const browser = await puppeteer.launch({
    executablePath: CHROME, headless: true,
    args: ["--no-sandbox", "--disable-dev-shm-usage"],
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 420, height: 900, isMobile: true, hasTouch: true });
  const errors = [];
  page.on("pageerror", (e) => errors.push("pageerror: " + e.message));
  page.on("console", (m) => { if (m.type() === "error") errors.push("console: " + m.text()); });

  /* ------------------------------------------- planet in sign page */
  await page.goto(BASE + "/planets/venus/scorpio/", { waitUntil: "networkidle0" });
  let text = await page.$eval("main", (el) => el.textContent);
  check("sign page: heading", text.includes("Venus in Scorpio"));
  check("sign page: wave1 text present", text.includes("In Scorpio, it tends to work in an intense, private, and probing way"));
  check("sign page: framing present", text.includes("colours how that part of a person tends to work"));
  let strip = await page.$eval(".next-clicks", (el) => el.innerHTML);
  let stripLinks = await page.$$eval(".next-clicks a", (els) => els.length);
  check("sign page: next-clicks strip with 24 links", stripLinks === 24, stripLinks + " links");
  check("sign page: strip crosses both ways", strip.includes("/planets/venus/aries/") && strip.includes("/planets/pluto/scorpio/"));
  let toolLinks = await page.$$eval('main a[href="/birth-chart/"]', (els) => els.length);
  check("sign page: links the chart tool in body", toolLinks >= 2, toolLinks + " tool links");
  await page.screenshot({ path: "/tmp/qa-w3-sign.png" });

  /* ------------------------------------------ planet in house page */
  await page.goto(BASE + "/houses/sun/9/", { waitUntil: "networkidle0" });
  text = await page.$eval("main", (el) => el.textContent);
  check("house page: heading", text.includes("Sun in the ninth house"));
  check("house page: wave1 text present", text.includes("In the ninth house"));
  check("house page: honest time note", text.includes("Houses need a birth time"));
  stripLinks = await page.$$eval(".next-clicks a", (els) => els.length);
  check("house page: next-clicks strip with 18 links", stripLinks === 18, stripLinks + " links");
  toolLinks = await page.$$eval('main a[href="/birth-chart/"]', (els) => els.length);
  check("house page: links the chart tool in body", toolLinks >= 2, toolLinks + " tool links");
  await page.screenshot({ path: "/tmp/qa-w3-house.png" });

  /* ------------------------------------------------------ sign page */
  await page.goto(BASE + "/signs/gemini/", { waitUntil: "networkidle0" });
  text = await page.$eval("main", (el) => el.textContent);
  check("sign hub: three starter readings", text.includes("Sun in Gemini") && text.includes("Moon in Gemini") && text.includes("Rising in Gemini"));
  check("sign hub: honest assembly note", text.includes("still being written"));
  let planetLinks = await page.$$eval('main a[href^="/planets/"][href$="/gemini/"]', (els) => els.length);
  check("sign hub: links all 10 planets in Gemini", planetLinks === 10, planetLinks + " links");
  stripLinks = await page.$$eval(".next-clicks a", (els) => els.length);
  check("sign hub: next-clicks strip with 14 links", stripLinks === 14, stripLinks + " links");
  await page.screenshot({ path: "/tmp/qa-w3-signgemini.png" });

  /* ---------------------------------------------------- library hub */
  await page.goto(BASE + "/library/", { waitUntil: "networkidle0" });
  text = await page.$eval("main", (el) => el.textContent);
  check("library hub: three families", text.includes("Planets in signs") && text.includes("Planets in houses") && text.includes("The signs"));
  let familyLinks = await page.$$eval('main a[href="/planets/"], main a[href="/houses/"]', (els) => els.length);
  check("library hub: family hub links", familyLinks >= 2, familyLinks + " links");
  let signLinks = await page.$$eval('main a[href^="/signs/"]', (els) => els.length);
  check("library hub: links all 12 signs", signLinks === 12, signLinks + " links");

  /* ------------------------------------------------- planets hub */
  await page.goto(BASE + "/planets/", { waitUntil: "networkidle0" });
  let allSignLinks = await page.$$eval('main a[href^="/planets/"][href*="/"]', (els) =>
    els.map((a) => a.getAttribute("href")).filter((h) => /^\/planets\/[a-z]+\/[a-z]+\/$/.test(h)).length);
  check("planets hub: links all 120 readings", allSignLinks === 120, allSignLinks + " links");

  /* --------------------------------------- N1 full reading (chart) */
  await page.goto(BASE + "/birth-chart/", { waitUntil: "networkidle0" });
  await pickPlace(page, "#birth-place", "#place-list", "New York", "New York");
  await setVal(page, "#birth-date", "1990-06-15");
  await setVal(page, "#birth-time", "14:30");
  await page.click('#chart-form button[type="submit"]');
  await page.waitForFunction(() => {
    const r = document.getElementById("result");
    return r && r.style.display !== "none" && r.textContent.includes("placement by placement");
  }, { timeout: 15000 });
  const blocks = await page.$$eval("#result .reading-block", (els) =>
    els.map((el) => (el.querySelector("h3") || {}).textContent || ""));
  check("N1: 18 reading blocks", blocks.length === 18,
    blocks.length + " blocks: " + blocks.join(" | ").slice(0, 220));
  check("N1: big three first", blocks[0].startsWith("Sun in") && blocks[1].startsWith("Moon in") && blocks[2].startsWith("Rising in"),
    blocks.slice(0, 3).join(" | "));
  const signBlocks = blocks.filter((b) => /^[A-Z][a-z]+ in [A-Z]/.test(b) && !b.includes("house"));
  const houseBlocks = blocks.filter((b) => b.includes("house"));
  check("N1: sign-titled blocks (big 3 + 10 in-sign)", signBlocks.length === 13, signBlocks.length + " sign-titled blocks");
  check("N1: 5 house readings", houseBlocks.length === 5, houseBlocks.join(" | "));
  const resultText = await page.$eval("#result", (el) => el.textContent);
  check("N1: full reading names houses", resultText.includes("in the 9th house") || resultText.includes("9th house"));
  check("N1: reading blocks link their library pages",
    resultText.includes("This reading also has its own page"));
  await page.screenshot({ path: "/tmp/qa-w3-chart.png", fullPage: false });

  /* --------------------- unknown time: signs only, no house blocks */
  await page.goto(BASE + "/birth-chart/", { waitUntil: "networkidle0" });
  await pickPlace(page, "#birth-place", "#place-list", "Berlin", "Berlin");
  await setVal(page, "#birth-date", "1985-03-04");
  await page.click("#time-unknown");
  await page.click('#chart-form button[type="submit"]');
  await page.waitForFunction(() => {
    const r = document.getElementById("result");
    return r && r.style.display !== "none" && r.textContent.includes("placement by placement");
  }, { timeout: 15000 });
  const uBlocks = await page.$$eval("#result .reading-block", (els) =>
    els.map((el) => (el.querySelector("h3") || {}).textContent || ""));
  check("unknown time: 13 reading blocks, no houses",
    uBlocks.length === 13 && !uBlocks.some((b) => b.includes("house")),
    uBlocks.length + " blocks");
  const uText = await page.$eval("#result", (el) => el.textContent);
  check("unknown time: honest notes kept",
    uText.includes("no houses") && uText.includes("planets in their signs only"));
  await page.screenshot({ path: "/tmp/qa-w3-unknown.png" });

  const realErrors = errors.filter((e) => !e.includes("favicon"));
  check("no page errors", realErrors.length === 0, realErrors.join(" | ").slice(0, 300));

  await browser.close();
  srv.close();
  const failed = results.filter((r) => !r.ok);
  console.log("\nQA SUMMARY: " + (results.length - failed.length) + "/" + results.length + " passed");
  process.exit(failed.length ? 1 : 0);
})().catch((e) => { console.error("QA CRASH:", e.message); process.exit(2); });
